  // way they would say it, about something true of them: a vet has done this before, a rookie has not.
  'captain-pitch.plan': [
    { id: 'cpt.p1', when: { rookieA: false }, turns: [{ by: 'a', say: "Look, I've done this before, and the team that loses is always the one standing around arguing about who goes where. If you pick me, I'll make those calls fast, and we can argue about them afterwards.",
      v: { sharp: "I've done this before. The team that loses is the one arguing about who goes where. Pick me and I'll make those calls fast.", dry: "I've done this before. Teams lose by standing around arguing about who goes where. I'd rather just make the call and hear the complaints later.", loud: "Look, I've done this BEFORE, and the team that loses is always the one standing around arguing about who goes where! Pick me and I'll make those calls fast!", soft: "I've done this before, and from what I've seen, the teams that lose are the ones that stand around arguing about who goes where. If you pick me, I'll try to make those calls quickly.", odd: "Look, I've done this before, and the team that loses is always the one standing around arguing about who goes where. Pick me and I'll make the calls fast. You can shout at me over dinner." } }] },
    { id: 'cpt.p2', when: { rookieA: true }, turns: [{ by: 'a', say: "I know I'm new, so hear me out. I've watched a lot of teams fall apart on this show because the captain was the loudest person there, and I'm not going to be that.",
      v: { sharp: "I know I'm new. I've watched a lot of teams fall apart because the captain was the loudest person there, and I won't be that.", dry: "I'm new, I know. I've watched plenty of teams fall apart under whoever was loudest. I'd like to try something else.", loud: "I know I'm NEW, so hear me out! I've watched so many teams fall apart because the captain was just the loudest person there, and I'm not going to be that!", soft: "I know I'm new here, so please hear me out. I've watched a lot of teams fall apart because the captain was the loudest one, and I really don't want to be that.", odd: "I know I'm new, so hear me out. I've watched a lot of teams fall apart because the captain was the loudest person there. I'm quite quiet. I think that helps." } }] },
    { id: 'cpt.p3', turns: [{ by: 'a', say: "I'm not going to stand here and shout at you. I've been watching all of you since we got here, and I already have a good idea who should be doing what tomorrow.",
      v: { sharp: "I'm not going to shout at you. I've watched all of you since we got here, and I know who should be doing what tomorrow.", dry: "I won't shout at you. I've been watching since we got here, and I've a fair idea who should do what tomorrow.", loud: "I'm not going to stand here and SHOUT at you! I've been watching all of you since we got here, and I already know who should be doing what tomorrow!", soft: "I'm not going to stand here and shout at anybody. I've been watching all of you since we got here, and I think I already know who should be doing what tomorrow.", odd: "I'm not going to stand here and shout at you. I've been watching all of you since we got here, quietly, which sounds worse than it is." } }] },
  ],
